function normalize(d){
    d=d||{}; d.schemaVersion=d.schemaVersion||1;
    d.title=d.title||"Untitled"; d.nodes=d.nodes||{}; d.links=Array.isArray(d.links)?d.links:[];
    d.groups=d.groups||{}; d.types=d.types||{};
    return d;
  }

load.code:
function load(d){
    doc=normalize(d);
    ids=Object.keys(doc.nodes);
    idx={}; ids.forEach((id,i)=>idx[id]=i);

    const n=ids.length; deg=new Int32Array(n); edges=[];
    for(const l of doc.links){
      const a=idx[l.from], b=idx[l.to];
      if(a===undefined||b===undefined) continue;
      edges.push(a,b); deg[a]++; deg[b]++;
    }
    const dv=Array.from(deg).filter(x=>x>0).sort((p,q)=>p-q);
    medianDeg=Math.max(1, dv.length?dv[dv.length>>1]:1);
  }

