function seedInto(){
    const ids=Model.ids, n=ids.length; Positions.ensure(n);
    const px=Positions.x, py=Positions.y, pz=Positions.z;
    for(let i=0;i<n;i++){ const u=seededUnit(String(ids[i])); px[i]=u[0]*R; py[i]=u[1]*R; pz[i]=u[2]*R; }
  }

run.code:
function run(onDone, onProgress){
    seedInto();
    const n=Model.count(), E=new Int32Array(Model.edges());
    if(worker){ worker.terminate(); worker=null; }
    if(workerURL){
      try{
        worker=new Worker(workerURL);
        worker.onmessage=(ev)=>{ const d=ev.data;
          Positions.x.set(d.px); Positions.y.set(d.py); Positions.z.set(d.pz);
          if(d.type==="progress"){ onProgress && onProgress(d.it, d.iters); }
          else if(d.type==="done"){ onDone&&onDone(d.ms,"worker"); } };
        worker.onerror=()=>{ runSync(n,E,onDone); };
        worker.postMessage({n, edges:E, px:Positions.x.slice(), py:Positions.y.slice(), pz:Positions.z.slice()});
        return;
      }catch(e){  }
    }
    runSync(n,E,onDone);
  }

run_sync.code:
function runSync(n,E,onDone){
    if(!runSyncSim){ onDone&&onDone(0,"seed-only"); return; }
    const t0=performance.now();
    runSyncSim(n, E, Positions.x, Positions.y, Positions.z, null, ()=>{});
    onDone&&onDone(Math.round(performance.now()-t0),"sync");
  }

deg_factor.code:
function degFactor(i){
  const d=Model.degOf(i); if(d<=0) return 0.7;
  return Math.max(0.6, Math.min(2.7, 0.15+0.85*Math.sqrt(d/Model.median())));
}

