      "#version 300 es\n in vec2 aCorner; uniform vec2 uViewport, uCenter, uHalf; out vec2 vT;\n void main(){ vT=vec2(aCorner.x*0.5+0.5, aCorner.y*0.5+0.5); vec2 px=uCenter+aCorner*uHalf; vec2 clip=(px/uViewport)*2.0-1.0; clip.y=-clip.y; gl_Position=vec4(clip,0.0,1.0); }",
      "#version 300 es\n precision highp float; in vec2 vT; uniform sampler2D uTex, uDepthTex; uniform float uAlpha, uLabelDepth; uniform vec2 uVP; uniform int uOcc; out vec4 o;\n void main(){ vec2 fc=vec2(gl_FragCoord.x, uVP.y-gl_FragCoord.y);\n   if(uOcc==1){ float sd=texture(uDepthTex, gl_FragCoord.xy/uVP).r; if(uLabelDepth > sd + 0.0015) discard; }   // sample the shape-accurate depth pre-pass; a nearer body (sphere OR flame) masks this pixel\n   vec4 c=texture(uTex,vT); o=vec4(c.rgb, c.a*uAlpha); }");
    if(!lProg) return;
