    const a=gl.getAttribLocation(lProg,"aCorner"); gl.enableVertexAttribArray(a); gl.vertexAttribPointer(a,2,gl.FLOAT,false,0,0); gl.bindVertexArray(null);
    ["uViewport","uCenter","uHalf","uTex","uAlpha","uDepthTex","uLabelDepth","uVP","uOcc"].forEach(k=>lU[k.slice(1)]=gl.getUniformLocation(lProg,k));
