function buildGalaxy(){ if(typeof Focus!=="undefined"&&Focus&&Focus._updateHlBtn) Focus._updateHlBtn();
    let seed=7; const rnd=()=>{seed=(seed*9301+49297)%233280;return seed/233280;};
    const grn=()=>(rnd()+rnd()+rnd()-1.5)/1.5;
    const tilt=0.5, ct=Math.cos(tilt), stlt=Math.sin(tilt);
    const bandDir=()=>{ const th=rnd()*6.2832; let x=Math.cos(th), z=Math.sin(th), y=grn()*0.12;
      const y2=y*ct - z*stlt, z2=y*stlt + z*ct; const L=Math.hypot(x,y2,z2)||1; return [x/L,y2/L,z2/L]; };
    const uniDir=()=>{ const u=rnd()*2-1, th=rnd()*6.2832, sq=Math.sqrt(1-u*u); return [Math.cos(th)*sq,u,Math.sin(th)*sq]; };
    const perturb=(d,amt)=>{ const x=d[0]+(rnd()-0.5)*amt, y=d[1]+(rnd()-0.5)*amt, z=d[2]+(rnd()-0.5)*amt, L=Math.hypot(x,y,z)||1; return [x/L,y/L,z/L]; };
    const mk=(d,hero,warmBias)=>{ const t=rnd(); const c=(rnd()<warmBias)?[255,236,206]:(t<0.6?[210,224,255]:(t<0.85?[255,255,255]:[255,238,216]));
      return {dx:d[0],dy:d[1],dz:d[2], r:hero?(2.2+rnd()*2):(0.5+rnd()*rnd()*1.9), a:hero?0.95:(0.32+rnd()*0.6), cs:"rgb("+c[0]+","+c[1]+","+c[2]+")", col:c, tw:rnd()<0.28?(0.6+rnd()*2.2):0, ph:rnd()*6.28, hero}; };

    // Star sphere: a fixed skybox (~22k points; warm core, bright band, scatter) re-projected only when the camera turns.
    bgStars=[]; const coreDir=bandDir();
    for(let i=0;i<2000;i++) bgStars.push(mk(perturb(coreDir,0.4+rnd()*0.8), rnd()<0.010, 0.5));
    for(let i=0;i<7500;i++) bgStars.push(mk(bandDir(), rnd()<0.008, 0.34));
    for(let i=0;i<13000;i++){ const st=mk(uniDir(), rnd()<0.004, 0.13); st.a*=0.85; bgStars.push(st); }

    bgGlow=[];
    for(let i=0;i<9;i++){ const d=perturb(coreDir,0.5+rnd()*0.7); bgGlow.push({dx:d[0],dy:d[1],dz:d[2], r:280+rnd()*300, col:[220,182,128], a:0.07+rnd()*0.06}); }
    for(let i=0;i<10;i++){ const d=bandDir(); bgGlow.push({dx:d[0],dy:d[1],dz:d[2], r:220+rnd()*280, col:(rnd()<0.5?[150,140,170]:[110,122,182]), a:0.04+rnd()*0.05}); }

    cloudSprites=[[210,168,120],[120,90,190],[52,128,168],[168,74,138],[86,104,196]].map((c,i)=>makeCloudSprite(c, 91+i*37));

    const RA=R, ct2=Math.cos(0.38), st2=Math.sin(0.38);
    const place=()=>{ const r=RA*(1.1+Math.pow(rnd(),0.7)*4.6), th=rnd()*6.2832; let x=Math.cos(th)*r, z=Math.sin(th)*r, y=grn()*r*0.13; return {x, y:y*ct2 - z*st2, z:y*st2 + z*ct2, r}; };
    bgMotes=[];
    for(let i=0;i<64;i++){ const p=place(); bgMotes.push({x:p.x,y:p.y,z:p.z, r:RA*(1.0+rnd()*2.4), spr:(rnd()*cloudSprites.length)|0, a:0.52+rnd()*0.44, rot:rnd()*6.28}); }
  }

