function frame(view){
    const n=Model.count(); ensure(n);
    // Per-frame effect geometry drawn by PlanetGL: additive fg lines, fg glows, behind-body coronas, over-blend ego/focus lines.
    let _EFL=[], _FGG=[], _BGG=[], _OVL=[];
    const lctx=PlanetGL.labelCtx();
    if(SolarSys.isSun && SolarSys.isSun.length!==n && typeof buildSolarTopology==="function"){ buildSolarTopology(); buildSolarOrbits(); }
    const px=Positions.x, py=Positions.y, pz=Positions.z;
    const cyaw=Math.cos(view.yaw),syaw=Math.sin(view.yaw),cp=Math.cos(view.pitch),sp=Math.sin(view.pitch);
    const cg=Math.cos(view.galAngle||0), sg=Math.sin(view.galAngle||0);
    const camYaw=view.yaw-spinAccum+((Focus.mode==="ego"||Focus.mode==="focus")?(view.galAngle||0):0), ccyaw=Math.cos(camYaw), csyaw=Math.sin(camYaw);
    const CX=W/2, CY=H/2, dist=view.dist, span=Layout.cloudRadius()*0.85, zoom=clamp(0.52,1.5,620/dist), margin=60;
    const _SD=SolarSys.systemDist||400, _fd=Focus.fitDist||_SD*3, cl=Math.max(0,Math.min(1,(_fd*2.6-dist)/(_fd*1.6)));
    const sysFade=Math.max(0,Math.min(1,(_fd*4.5-dist)/(_fd*2.0)));
    const densityScale=Math.max(0.32, Math.min(1, Math.sqrt(160/Math.max(1,n))));

    const nowT=(typeof performance!=="undefined"?performance.now():Date.now());
    const bdx=-BM - Math.sin(view.yaw)*BM*0.55 + Math.sin(nowT*0.00004)*6;
    const bdy=-BM - Math.max(-BM*0.6,Math.min(BM*0.6, Math.sin(view.pitch)*BM*0.7)) + Math.cos(nowT*0.00003)*5;

    if(typeof window!=="undefined"&&window._launcherOpen){ return; }

    let cnt=0;
    if(!(_warp && !_warp.loaded) && Focus.planetFocus>=0){ const _gp=galaxyPosNow(Focus.planetFocus); if(_gp){ view.cx=_gp.x*cg - _gp.z*sg; view.cy=_gp.y; view.cz=_gp.x*sg + _gp.z*cg; } }
    const lax=view.cx, lay=view.cy, laz=view.cz;
    const fSkip = Focus.mode==="focus" ? Focus.skip : null, dim = fSkip?0.5:1;
    const ego = Focus.mode==="ego", ec = ego && Focus.egoCenter>=0 ? Focus.egoCenter : -1;
    for(let i=0;i<n;i++){
      if(fSkip && fSkip[i]){ proj.vis[i]=0; continue; }
      if(visFlags && !visFlags[i]){ proj.vis[i]=0; proj.front[i]=0; continue; }

      let bx=px[i], by=py[i], bz=pz[i];
      { const orb=SolarSys.orbit[i];
        if(orb && SolarSys.sunX){ const su=orb.su, th=orb.phase+orb.speed*planetT*0.001, cs=Math.cos(th), sn=Math.sin(th);
          bx=SolarSys.sunX[su]+orb.r*(cs*orb.ux+sn*orb.vx); by=SolarSys.sunY[su]+orb.r*(cs*orb.uy+sn*orb.vy); bz=SolarSys.sunZ[su]+orb.r*(cs*orb.uz+sn*orb.vz); }
