function pick(mx,my){ const n=Model.count();

    let best=-1, bestAz=Infinity;
    for(let i=0;i<n;i++){ if(!proj.vis[i]) continue; const rr=proj.r[i];
      const ddx=mx-proj.x[i], ddy=my-proj.y[i]; if(ddx*ddx+ddy*ddy<rr*rr && proj.az[i]<bestAz){ bestAz=proj.az[i]; best=i; } }
    if(best>=0) return best;

    let bestD=Infinity;
    for(let i=0;i<n;i++){ if(!proj.vis[i]) continue; const rr=Math.max(26,proj.r[i]);
      const ddx=mx-proj.x[i], ddy=my-proj.y[i], d2=ddx*ddx+ddy*ddy; if(d2<rr*rr && d2<bestD){ bestD=d2; best=i; } }
    return best; }

pick_connector.code:
function pickConnector(mx,my){
    if(Focus.mode!=="ego" || Focus.egoCenter<0 || !proj.vis[Focus.egoCenter]) return -1;
    const cx=proj.x[Focus.egoCenter], cy=proj.y[Focus.egoCenter]; let best=-1, bestD=(IS_TOUCH?26:24), n=Model.count();
    for(let i=0;i<n;i++){ if(!Focus.egoDir[i] || !proj.vis[i]) continue;
      const d=segDist(mx,my, cx,cy, proj.x[i],proj.y[i]); if(d<bestD){ bestD=d; best=i; } }
    return best; }

