function pickAnyConnector(mx,my){ const E=Model.edges(); let best=null, bestD=(IS_TOUCH?26:24);
    for(let k=0;k<E.length;k+=2){ const a=E[k],b=E[k+1]; if(!proj.front[a]||!proj.front[b]) continue;
      const d=segDist(mx,my, proj.x[a],proj.y[a], proj.x[b],proj.y[b]); if(d<bestD){ bestD=d; best={a,b}; } }
    if(best){ const da=(mx-proj.x[best.a])**2+(my-proj.y[best.a])**2, db=(mx-proj.x[best.b])**2+(my-proj.y[best.b])**2; if(db<da){ const t=best.a; best.a=best.b; best.b=t; } }
    return best; }

seg_dist.code:
function segDist(px,py, ax,ay, bx,by){ const dx=bx-ax, dy=by-ay, l2=dx*dx+dy*dy;
  let t=l2>0?((px-ax)*dx+(py-ay)*dy)/l2:0; t=Math.max(0,Math.min(1,t));
  return Math.hypot(px-(ax+t*dx), py-(ay+t*dy)); }

universe_fit_dist.code:
function universeFitDist(){
  const half0=Math.max(60, Math.min(innerWidth, innerHeight)/2 - 30);
  if(SolarSys.galaxyR) return Math.max(R*2.0, SolarSys.galaxyR*1.15*F/half0);
  const n=Model.count(); if(!n) return R*3.4;
  const rs=new Float64Array(n);
  for(let i=0;i<n;i++) rs[i]=Math.hypot(Positions.x[i],Positions.y[i],Positions.z[i]);
  rs.sort();
  const rHi=rs[Math.floor((n-1)*0.95)]||R;
  const half=Math.max(60, Math.min(innerWidth, innerHeight)/2 - 30);
  return Math.max(R*2.4, rHi*F/half);
}

