function legendEntries(){
  const groups=Model.raw.groups||{}, ids=Model.ids;
  const entries=Object.keys(groups).map(k=>({k, label:groups[k].label||k, color:(PAL[groups[k].color]||PAL.gray)[3]}));
  if(Object.keys(groups).length && ids.some(id=>!groupOf(id))) entries.push({k:"", label:"Ungrouped", color:PAL.gray[3]});
  return entries;
}

