function paintLegendInto(elId){
  const lg=document.getElementById(elId); if(!lg) return; lg.innerHTML="";
  legendEntries().forEach(en=>{ const s=document.createElement("span"); s.className="leg"; s.title="Show / hide this group";
    if(hiddenGroups[en.k]){ s.style.opacity="0.4"; s.style.textDecoration="line-through"; }
    s.innerHTML='<span class="dot" style="background:'+en.color+'"></span>'+esc(en.label);
    s.onclick=()=>toggleGroup(en.k); lg.appendChild(s); });
}

