function syncTopbar(){
  const tb=document.getElementById("topbar"); if(!tb) return;
  const inCard = Focus.mode==="focus";
  tb.style.display = inCard ? "flex" : "none";
  const tt=document.getElementById("topbar-title"); if(tt) tt.textContent = Model.title()||"";
  const lg=document.getElementById("legend"); if(lg) lg.style.display = inCard ? "none" : "";
  ["zoomctl","spinctl","spinpad","breadcrumb"].forEach(id=>{ const el=document.getElementById(id); if(el) el.style.display = inCard ? "none" : "flex"; });
  if(inCard) buildTopbarLegend();
}

