function toggleGroup(k){
  hiddenGroups[k]=!hiddenGroups[k];
  if(!Model.ids.some(isVisible)){ hiddenGroups[k]=!hiddenGroups[k]; return; }
  rebuildVis(); buildLegend();
  if(Focus.mode==="focus"){ if(isVisible(Focus.id)) enterFocus(Focus.id); else exitFocus(); }
}

