function neighboursOf(id){
  const raw=Model.raw, types=raw.types||{}, seen={}, out=[];
  for(const l of raw.links){
    let other=null, rel=null, dir=0; const t=types[l.type]||{mutual:true}; const directional=!t.mutual && t.arrow!==false;
    if(l.from===id){ other=l.to; rel=t.mutual?(t.label||l.type):(t.toLabel||t.label||l.type); if(directional) dir=1; }
    else if(l.to===id){ other=l.from; rel=t.mutual?(t.label||l.type):(t.fromLabel||t.label||l.type); if(directional) dir=-1; }
    if(other && Model.nodeById(other)){
      if(!seen[other]){ seen[other]={id:other, rels:[], dir:0, dashed:false}; out.push(seen[other]); }
      if(rel && seen[other].rels.indexOf(rel)<0) seen[other].rels.push(rel);
      if(dir!==0 && seen[other].dir===0) seen[other].dir=dir;
      if(t.dashed) seen[other].dashed=true;
    }
  }
  return out.map(r=>({ id:r.id, rel:r.rels.join(" \u00b7 ").toUpperCase(), dir:r.dir, dashed:r.dashed }));
}

