function toEdge(ox,oy,tx,ty,hw,hh){ const dx=tx-ox,dy=ty-oy;
  const fx=dx!==0?hw/Math.abs(dx):1e9, fy=dy!==0?hh/Math.abs(dy):1e9, t=Math.min(1,Math.min(fx,fy));
