function buildFocusCards(){
  const host=document.getElementById("cards"); host.innerHTML="";
  if(Focus.mode!=="focus"||!Focus.id) return;
  const W=innerWidth, H=innerHeight, CX=W/2, CY=H/2;
  const nbrs=Focus.neighbours, N=nbrs.length;
  const manyNbr=N>14;
  const tb=document.getElementById("topbar");
  const topInset=(tb && tb.offsetHeight) ? tb.offsetHeight+6 : 44;
  const botInset=54;

  const fc=buildFocusCenterCard(host, CX, CY);
  const cards=[];
  for(let k=0;k<N;k++){ const card=makeCard(nbrs[k].id, false, nbrs[k].rel, !manyNbr); host.appendChild(card); cards.push(card); }

  let fw=fc.offsetWidth, fh=fc.offsetHeight;
  const sz=cards.map(c=>({w:c.offsetWidth, h:c.offsetHeight}));
  const Lb=0, Rb=W, Tb=topInset, Bb=H-botInset, targets=[];
  const _avgW=sz.length?sz.reduce((a,c)=>a+c.w,0)/sz.length:150, _avgH=sz.length?sz.reduce((a,c)=>a+c.h,0)/sz.length:60, _maxNW=sz.length?Math.max.apply(null,sz.map(c=>c.w)):_avgW;
  const _approxP=2*((Rb-Lb-_avgW)+(Bb-Tb-_avgH));
  let baseScale=Math.max(0.6, Math.min(1.6, (_approxP/Math.max(1,N)*0.8)/Math.max(90,_avgW)));
  baseScale=Math.min(baseScale, 1.0);
  baseScale=Math.max(0.55, baseScale);
  { const _maxCW=Math.max(180, W - 2*_maxNW*baseScale - 36); if(fw>_maxCW){ const _inner=fc.firstElementChild; if(_inner){ _inner.style.boxSizing="border-box"; _inner.style.width=Math.round(_maxCW)+"px"; } fw=fc.offsetWidth; fh=fc.offsetHeight; } }
  const _hw=_avgW/2*baseScale+8, _hh=_avgH/2*baseScale+8;
  const _pL=Lb+_hw, _pR=Rb-_hw, _pT=Tb+_hh, _pB=Bb-_hh, _rw=Math.max(1,_pR-_pL), _rh=Math.max(1,_pB-_pT);
  const _r=Math.max(30, Math.min(_rw,_rh)*0.28), _sTop=Math.max(1,_rw-2*_r), _sRight=Math.max(1,_rh-2*_r), _sArc=Math.PI*_r/2, _perimR=2*(_sTop+_sRight)+4*_sArc;
  function _rr(s){ s=((s%_perimR)+_perimR)%_perimR;
    if(s<_sTop) return [_pL+_r+s, _pT]; s-=_sTop;
    if(s<_sArc){ const a=-Math.PI/2+s/_r; return [_pR-_r+_r*Math.cos(a), _pT+_r+_r*Math.sin(a)]; } s-=_sArc;
    if(s<_sRight) return [_pR, _pT+_r+s]; s-=_sRight;
    if(s<_sArc){ const a=s/_r; return [_pR-_r+_r*Math.cos(a), _pB-_r+_r*Math.sin(a)]; } s-=_sArc;
    if(s<_sTop) return [_pR-_r-s, _pB]; s-=_sTop;
    if(s<_sArc){ const a=Math.PI/2+s/_r; return [_pL+_r+_r*Math.cos(a), _pB-_r+_r*Math.sin(a)]; } s-=_sArc;
    if(s<_sRight) return [_pL, _pB-_r-s]; s-=_sRight;
    const a=Math.PI+s/_r; return [_pL+_r+_r*Math.cos(a), _pT+_r+_r*Math.sin(a)]; }
  const layout={ fx:CX, fy:CY, fw, fh, nbrs:[] };
  fc.style.opacity="0";
  for(let k=0;k<N;k++){

    let _p=_rr(_sTop/2 + (k/N)*_perimR), tx=_p[0], ty=_p[1];
    const nw=sz[k].w, nh=sz[k].h, nvs=baseScale, hw=nw/2*nvs+6, hh=nh/2*nvs+6;
    tx=Math.max(Lb+hw, Math.min(Rb-hw, tx)); ty=Math.max(Tb+hh, Math.min(Bb-hh, ty));
    const cardHalfW=fw/2+hw+8, cardHalfH=fh/2+hh+8, ddx=tx-CX, ddy=ty-CY;
    if(Math.abs(ddx)<cardHalfW && Math.abs(ddy)<cardHalfH){
      const axr=Math.abs(ddx)||1e-4, ayr=Math.abs(ddy)||1e-4, ts=Math.min(cardHalfW/axr, cardHalfH/ayr);
      tx=CX+ddx*ts; ty=CY+ddy*ts; tx=Math.max(Lb+hw, Math.min(Rb-hw, tx)); ty=Math.max(Tb+hh, Math.min(Bb-hh, ty));
      if(Math.abs(tx-CX)<cardHalfW && Math.abs(ty-CY)<cardHalfH){ const dir=ddy<=0?-1:1; ty=Math.max(Tb+hh, Math.min(Bb-hh, CY+dir*cardHalfH)); }
    }
    const card=cards[k], nid=nbrs[k].id;
    if(Focus.pinned[nid]){ tx=Focus.pinned[nid].x; ty=Focus.pinned[nid].y; }

    card.style.left=CX+"px"; card.style.top=CY+"px"; card.style.opacity="0";
    card.style.transform="translate(-50%,-50%) scale("+nvs.toFixed(3)+")";
    card.onclick=()=>{ if(card._lp){ card._lp=false; return; } const central=Focus.id; egoTo(central); const ni=Model.index(nid); if(ni!==undefined) focusPlanet(ni); };
    card.addEventListener("dblclick", (ev)=>{ ev.stopPropagation(); enterCardEdit({kind:"node", id:nid}); });
    attachLongPress(card, ()=>{ enterCardEdit({kind:"node", id:nid}); });
    attachCardDrag(card, nid, layout.nbrs.length);
    targets.push({card, tx, ty, hw, hh});
    layout.nbrs.push({ id:nid, x:tx, y:ty, w:nw*nvs, h:nh*nvs, dir:nbrs[k].dir, dashed:nbrs[k].dashed });
  }

  for(let it=0; it<16; it++){ let any=false;
    for(let a=0;a<targets.length;a++){ const A=targets[a];
      for(let b2=a+1;b2<targets.length;b2++){ const B=targets[b2];
        const dx=B.tx-A.tx, dy=B.ty-A.ty, ox=(A.hw+B.hw+4)-Math.abs(dx), oy=(A.hh+B.hh+4)-Math.abs(dy);
        if(ox>0 && oy>0){ if(ox<oy){ const p=ox/2*(dx<0?-1:1)||ox/2; A.tx-=p; B.tx+=p; } else { const p=oy/2*(dy<0?-1:1)||oy/2; A.ty-=p; B.ty+=p; } any=true; }
      } }
    if(!any) break;
  }
  targets.forEach(t=>{ t.tx=Math.max(Lb+t.hw, Math.min(Rb-t.hw, t.tx)); t.ty=Math.max(Tb+t.hh, Math.min(Bb-t.hh, t.ty));
    const chw=fw/2+t.hw+8, chh=fh/2+t.hh+8, ddx=t.tx-CX, ddy=t.ty-CY;
    if(Math.abs(ddx)<chw && Math.abs(ddy)<chh){ const ts=Math.min(chw/(Math.abs(ddx)||1e-4), chh/(Math.abs(ddy)||1e-4)); t.tx=CX+ddx*ts; t.ty=CY+ddy*ts; t.tx=Math.max(Lb+t.hw, Math.min(Rb-t.hw, t.tx)); t.ty=Math.max(Tb+t.hh, Math.min(Bb-t.hh, t.ty)); } });
  for(let k=0;k<targets.length && k<layout.nbrs.length;k++){ layout.nbrs[k].x=targets[k].tx; layout.nbrs[k].y=targets[k].ty; }

  { const nbrIdx={}; layout.nbrs.forEach((nb,ix)=>nbrIdx[nb.id]=ix);
    const raw=Model.raw, types=raw.types||{}, pairCount={}, pairSeen={}, edges=[];
    for(const l of (raw.links||[])){
      let other=null, dir=0; const t=types[l.type]||{mutual:true}, directional=!t.mutual && t.arrow!==false;
      if(l.from===Focus.id){ other=l.to; if(directional) dir=1; }
      else if(l.to===Focus.id){ other=l.from; if(directional) dir=-1; }
      if(other==null || nbrIdx[other]===undefined) continue;
      pairCount[other]=(pairCount[other]||0)+1;
      edges.push({nbrIdx:nbrIdx[other], other, dir, dashed:!!t.dashed, off:0});
    }
    edges.forEach(ed=>{ if(pairCount[ed.other]>1){ const i=pairSeen[ed.other]||0; ed.off=i===0?-9:9; pairSeen[ed.other]=i+1; } });
    layout.edges=edges;
  }
  Focus.layout=layout; Focus.t0=(typeof performance!=="undefined"?performance.now():Date.now());
  const paint=()=>{ fc.style.opacity="1"; for(const t of targets){ t.card.style.left=t.tx+"px"; t.card.style.top=t.ty+"px"; t.card.style.opacity="1"; } };
  if(typeof requestAnimationFrame!=="undefined") requestAnimationFrame(()=>requestAnimationFrame(paint)); else paint();
}

