function buildSolarTopology(){
  const n=Model.count(); const deg=new Int32Array(n);
  for(let i=0;i<n;i++) deg[i]=Model.degOf(i);
  const E=Model.edges(); const adj=Array.from({length:n},()=>[]);
  for(let k=0;k<E.length;k+=2){ const a=E[k],b=E[k+1]; if(a<n&&b<n){ adj[a].push(b); adj[b].push(a); } }
  const _ds=Array.from(deg).sort((a,b)=>a-b), SUN_MIN=Math.max(3, _ds[Math.floor(n*0.80)]||3);
  const startId=(Model.raw&&Model.raw.start!=null)?Model.raw.start:null, startIdx=(startId!=null)?Model.index(startId):undefined;
  const homeOf=(i,isSun)=>{ let bi=-1,bd=-1; const A=adj[i]; for(let x=0;x<A.length;x++){ const j=A[x]; if(isSun[j]&&(deg[j]>bd||(deg[j]===bd&&j>bi))){bd=deg[j];bi=j;} } return bi; };
  const cover=(isSun)=>{ for(let i=0;i<n;i++){ if(isSun[i]||deg[i]===0) continue; let has=false; const A=adj[i]; for(let x=0;x<A.length;x++) if(isSun[A[x]]){has=true;break;} if(!has) isSun[i]=1; } };
  const assignHomes=(isSun,forceF)=>{ const sun=new Int32Array(n); const fset=forceF!==undefined?new Set(adj[forceF]):null;
    for(let i=0;i<n;i++){ if(isSun[i]){sun[i]=i;continue;} if(fset&&fset.has(i)){sun[i]=forceF;continue;} const bi=homeOf(i,isSun); sun[i]=bi>=0?bi:i; } return sun; };

  const idealIsSun=new Uint8Array(n);
  if(startIdx!==undefined) idealIsSun[startIdx]=1;
  for(let i=0;i<n;i++) if(deg[i]>=SUN_MIN) idealIsSun[i]=1;
  cover(idealIsSun);
  const idealSun=assignHomes(idealIsSun);
  SolarSys.homeSun=Int32Array.from(idealSun); SolarSys.homeIsSun=Uint8Array.from(idealIsSun);

  const isSun=Uint8Array.from(idealIsSun); let sun;
  if(startIdx!==undefined){
    const A=adj[startIdx]; for(let x=0;x<A.length;x++){ if(A[x]!==startIdx) isSun[A[x]]=0; }
    cover(isSun);
    sun=assignHomes(isSun, startIdx);
  } else { sun=assignHomes(isSun); }
  SolarSys.sun=sun; SolarSys.isSun=isSun; SolarSys.orbit=new Array(n).fill(null); SolarSys.disp=[]; SolarSys.fade=[];
}

