function buildSolarOrbits(keep){
  const n=Model.count(); if(SolarSys.sun.length!==n) return;
  const isSun=SolarSys.isSun, assign=SolarSys.sun;
  const suns=[]; for(let i=0;i<n;i++) if(isSun[i]) suns.push(i);
  suns.sort((a,b)=> Model.degOf(b)-Model.degOf(a) || a-b);
  const NS=suns.length;
  const CR=(Layout.cloudRadius&&Layout.cloudRadius())||300;
  const Rb=CR*0.05, PER=7;

  const bySun={}; for(let i=0;i<n;i++){ const su=assign[i]; if(su>=0 && su!==i && isSun[su]) (bySun[su]||(bySun[su]=[])).push(i); }
  for(const su in bySun) bySun[su].sort((a,b)=> Model.degOf(a)-Model.degOf(b) || a-b);

  const orbit=new Array(n).fill(null), sysR=new Float64Array(n), sunRArr=new Float64Array(n);
  for(let s=0;s<NS;s++){ const su=suns[s], pl=bySun[su]||[];
    const h=((su*2654435761)>>>0)/4294967296, h2=((su*40503+13)>>>0)/4294967296;
    const node0=h2*6.283;
    const cnt=pl.length; let maxr=Rb;
    const maxDeg=Math.max(1, ...pl.map(j=>Model.degOf(j)));
    const pR=pl.map(pj=>(0.32 + 3.6*Math.pow(Model.degOf(pj)/maxDeg,1.05))*Rb*0.5);
    const sunR=(cnt?Math.max(...pR):Rb*0.3)*1.32 + Rb*0.4; sunRArr[su]=sunR;
    let edge=Math.max(Rb*2.2, sunR + Rb*1.5);
    pl.forEach((i,k)=>{ const f = cnt>1 ? k/(cnt-1) : 0.3;
      const hk=((i*2654435761)>>>0)/4294967296, hk3=((i*2246822519)>>>0)/4294967296;
      const pInc=(hk-0.5)*0.22, pNode=node0+(hk3-0.5)*1.5;
      const cn=Math.cos(pNode), sn=Math.sin(pNode), ci=Math.cos(pInc), si=Math.sin(pInc);
      const U={x:cn,y:0,z:sn}, V={x:-sn*ci,y:si,z:cn*ci};
      const pWorldR = pR[k];
      const baseGap = Rb*(0.05 + 0.5*Math.pow(1-f,1.7));
      const spaceR = pWorldR;
      const r = edge + baseGap + spaceR;
      edge = r + spaceR; maxr = Math.max(maxr, r);
      const phase = k*2.39996323 + (hk-0.5)*0.4;
      const speed = 0.28*Math.pow(Rb*5/r, 1.5);
      const degN = Model.degOf(i)/maxDeg, tidal = Math.min(1, Math.max(0, (r/Rb - 4)/8));
      const spin = (0.35 + 1.7*degN) * (0.1 + 0.9*tidal) * (hk3 < 0.72 ? 1 : -0.6);
      orbit[i] = { su, r, ux:U.x,uy:U.y,uz:U.z, vx:V.x,vy:V.y,vz:V.z, phase, speed, pWorldR, spin };
    });
    sysR[su]=maxr + Rb*0.55;
  }
  let sunX,sunY,sunZ,placed,galaxyR;
  if(keep && SolarSys.sunX && SolarSys.sunX.length===n){
    sunX=SolarSys.sunX; sunY=SolarSys.sunY; sunZ=SolarSys.sunZ; placed=SolarSys.placed; galaxyR=SolarSys.galaxyR||CR*1.6;
  } else {

  const HALO=CR*0.28;
  let sumA=0; for(let s=0;s<NS;s++){ const e=sysR[suns[s]]+HALO; sumA += e*e; }
  galaxyR=Math.max(CR*1.6, Math.sqrt(Math.max(1,sumA))*2.3);
  const ARMS=(NS>60?4:NS>16?3:2), TW=2.3;
  let rs=97; const rr=()=>{ rs=(rs*1103515245+12345)&0x7fffffff; return rs/0x7fffffff; };
  sunX=new Float64Array(n); sunY=new Float64Array(n); sunZ=new Float64Array(n); placed=new Uint8Array(n);

  for(let s=0;s<NS;s++){ const su=suns[s], t=NS>1?s/(NS-1):0;
    const rad=galaxyR*(0.14+0.86*Math.pow(t,0.82)), arm=s%ARMS;
    const theta=arm*(2*Math.PI/ARMS) + (rad/galaxyR)*TW*2*Math.PI + (rr()-0.5)*0.55;
    const aw=(rr()-0.5)*galaxyR*0.08;
    sunX[su]=Math.cos(theta)*rad - Math.sin(theta)*aw;
    sunZ[su]=Math.sin(theta)*rad + Math.cos(theta)*aw;
    sunY[su]=(rr()-0.5)*galaxyR*0.05*Math.exp(-rad/galaxyR*2.0); placed[su]=1;
  }

  if(NS>1) for(let pass=0;pass<18;pass++){ let moved=false;
    for(let a=0;a<NS;a++) for(let b=a+1;b<NS;b++){ const i=suns[a], j=suns[b], D=sysR[i]+sysR[j]+CR*0.5;
      let dx=sunX[i]-sunX[j], dy=sunY[i]-sunY[j], dz=sunZ[i]-sunZ[j], dd=Math.sqrt(dx*dx+dy*dy+dz*dz);
      if(dd<1e-3){ dx=rr()-0.5; dy=rr()-0.5; dz=rr()-0.5; dd=Math.sqrt(dx*dx+dy*dy+dz*dz)||1; }
      if(dd<D){ const p=(D-dd)*0.5/dd; sunX[i]+=dx*p; sunY[i]+=dy*p; sunZ[i]+=dz*p; sunX[j]-=dx*p; sunY[j]-=dy*p; sunZ[j]-=dz*p; moved=true; } }
    if(!moved) break; }

  for(let i=0;i<n;i++){ if(isSun[i] || assign[i]!==i) continue;
    const g=((i*2246822519)>>>0)/4294967296, g2=((i*3266489917)>>>0)/4294967296, rad=galaxyR*Math.sqrt(g)*0.98, th=g2*6.283;
    sunX[i]=Math.cos(th)*rad; sunZ[i]=Math.sin(th)*rad; sunY[i]=(g-0.5)*galaxyR*0.05; placed[i]=1; }
  }
  SolarSys.orbit=orbit; SolarSys.sunR=sunRArr; SolarSys.sunX=sunX; SolarSys.sunY=sunY; SolarSys.sunZ=sunZ; SolarSys.placed=placed; SolarSys.Rmax=Rb; SolarSys.galaxyR=galaxyR; SolarSys.systemDist=Rb*11;
}

