function promote(F, inPlace){
  const S=SolarSys, n=Model.count(); if(!S.sunX || S.sunX.length!==n) return;
  const deg=new Int32Array(n); for(let i=0;i<n;i++) deg[i]=Model.degOf(i);
  const E=Model.edges(), adj=Array.from({length:n},()=>[]);
  for(let k=0;k<E.length;k+=2){ const a=E[k],b=E[k+1]; if(a<n&&b<n){ adj[a].push(b); adj[b].push(a); } }
  const nbrF=new Set(adj[F]);
  if(!S.isSun[F]){
    const H=S.sun[F];
    if(!inPlace && H>=0 && H!==F && S.isSun[H] && S.placed[H]){ S.sunX[F]=S.sunX[H]; S.sunY[F]=S.sunY[H]; S.sunZ[F]=S.sunZ[H]; }
    else { const d=inPlace?galaxyPosNow(F):((S.disp&&S.disp[F])||galaxyPosNow(F)); S.sunX[F]=d.x; S.sunY[F]=d.y; S.sunZ[F]=d.z; }
    S.placed[F]=1;
  }
  S.isSun[F]=1; S.sun[F]=F; S.orbit[F]=null;
  const orphans=[];
  for(const j of adj[F]){ if(j===F) continue;
    if(S.isSun[j]){ for(let k=0;k<n;k++){ if(k!==j && S.sun[k]===j && !nbrF.has(k)) orphans.push(k); } S.isSun[j]=0; S.placed[j]=0; }
    S.sun[j]=F;
  }
  for(const k of orphans){ if(nbrF.has(k) || S.sun[k]===F) continue;
    let best=-1,bd=-1; for(const s of adj[k]){ if(s!==k && S.isSun[s] && deg[s]>bd){ bd=deg[s]; best=s; } }
    if(best>=0){ S.sun[k]=best; S.isSun[k]=0; }
    else { S.isSun[k]=1; S.sun[k]=k;
      const ang=((k*2654435761)>>>0)/4294967296*6.283, rr=(S.galaxyR||300)*1.03;
      S.sunX[k]=Math.cos(ang)*rr; S.sunZ[k]=Math.sin(ang)*rr; S.sunY[k]=(((k*40503)%100)/100-0.5)*(S.galaxyR||300)*0.05; S.placed[k]=1; }
  }
  buildSolarOrbits(true);
  SolarSys.morph=0.07;
}

