  let s=99991; const rnd=()=>{s=(s*1103515245+12345)&0x7fffffff;return s/0x7fffffff;};
  for(let i=0;i<n;i++) nodes["n"+i]={name:"Node "+i, group:"g_"+PAL_SELECTABLE[(rnd()*PAL_SELECTABLE.length)|0]};
  const targets=[0,0,0];
  for(let i=1;i<n;i++){ const picks=new Set();
    for(let k=0;k<2&&targets.length;k++){ const t=targets[(rnd()*targets.length)|0]; if(t!==i&&!picks.has(t)) picks.add(t); }
    picks.forEach(t=>{ links.push({from:"n"+i,to:"n"+t,type:"link"}); targets.push(i,t); }); }
  return {schemaVersion:1, title:"Synthetic "+n, nodes, links, groups, types};
}

