    const nk=slugKey(k, TYPES); TYPES[nk]=t2; typeMap[k]=nk; });
  const idMap={}, newIds=[]; let mergedCount=0, addedCount=0;
  Object.keys(data2.nodes).forEach(k=>{ const nd2=data2.nodes[k], matchId=findMergeMatch(nd2);
    if(matchId){ fillGaps(N[matchId], nd2, groupMap); idMap[k]=matchId; mergedCount++; return; }
    const nk=slugKey(k, N), nd=JSON.parse(JSON.stringify(nd2));
    if(nd.group) nd.group=groupMap[nd.group]||nd.group;
    N[nk]=nd; idMap[k]=nk; newIds.push(nk); addedCount++; });
  (data2.links||[]).forEach(l=>{ if(!idMap[l.from]||!idMap[l.to]) return;
    const ty=(l.type in typeMap)?typeMap[l.type]:l.type, from=idMap[l.from], to=idMap[l.to];
    if(from===to) return;
    if(Model.raw.links.some(x=>x.from===from&&x.to===to&&x.type===ty)) return;
    Model.raw.links.push({from,to,type:ty}); });

  Model.load(Model.raw); Positions.ensure(Model.count());
  Model.ids.forEach((k,i)=>{ const p=snap[k]; if(p){ Positions.x[i]=p.x; Positions.y[i]=p.y; Positions.z[i]=p.z; } });
  const fi = Focus.id!=null ? Model.index(Focus.id) : undefined;
  const fx = fi!==undefined ? Positions.x[fi] : 0, fy = fi!==undefined ? Positions.y[fi] : 0, fz = fi!==undefined ? Positions.z[fi] : 0;
  newIds.forEach(id=>{ const i=Model.index(id); if(i===undefined) return;
    Positions.x[i]=fx+Math.random()*260-130; Positions.y[i]=fy+Math.random()*180-90; Positions.z[i]=fz+Math.random()*260-130; });
  rebuildVis(); buildLegend(); rebuildJump(); Renderer.refresh();
  if(Focus.mode==="ego") egoTo(Focus.id); else if(Focus.mode==="focus") enterFocus(Focus.id);
  saveRoot();
  if(mergedCount||addedCount) showInfoCard("Merged "+mergedCount+" matching node"+(mergedCount===1?"":"s")+" and added "+addedCount+" new node"+(addedCount===1?"":"s")+".");
}

each_media_field.code:
function eachMediaField(ds, fn, seen){
  seen=seen||new Set(); if(!ds||seen.has(ds)) return ds; seen.add(ds);
  Object.values(ds.nodes||{}).forEach(nd=>{ MEDIA_FIELDS.forEach(([f])=>fn(nd, f)); if(nd.subgraph) eachMediaField(nd.subgraph, fn, seen); });
  (ds.links||[]).forEach(l=>{ if(l&&l.subgraph) eachMediaField(l.subgraph, fn, seen); });
  Object.values(ds._subgraphs||{}).forEach(sg=>eachMediaField(sg, fn, seen));
  return ds;
}

