function hasBundleableMedia(ds){
  let found=false; eachMediaField(ds, (nd,f)=>{ if(nd[f] && !/^https?:/i.test(nd[f])) found=true; }); return found;
}

collect_and_extract_media.code:
function collectAndExtractMedia(ds, zip, pathPrefix, seen){ seen=seen||new Set(); if(!ds||seen.has(ds)) return; seen.add(ds);
  for(const id of Object.keys(ds.nodes||{})){ const nd=ds.nodes[id];
    for(const [field,folder] of MEDIA_FIELDS){ const v=nd[field]; if(!v) continue;
      const m=v.match(/^data:image\/([a-z0-9.+-]+);base64,(.*)$/i);
      if(m){ const ext=(m[1].toLowerCase()==="jpeg")?"jpg":m[1].toLowerCase().replace(/[^a-z0-9]/g,"");
        const fn=pathPrefix+folder+"/"+id+"."+ext; zip.file(fn, m[2], {base64:true}); nd[field]=fn; }
      else if(!/^https?:/i.test(v)){
        try{ const buf=await (await fetch(v)).arrayBuffer(); const ext=(v.split(".").pop()||"jpg").toLowerCase().replace(/[^a-z0-9]/g,"");
          const fn=pathPrefix+folder+"/"+id+"."+ext; zip.file(fn, buf); nd[field]=fn; }catch(e){  } }
    }
    if(nd.subgraph) await collectAndExtractMedia(nd.subgraph, zip, pathPrefix+"subgraphs/"+id+"/", seen);
  }
  for(let i=0;i<(ds.links||[]).length;i++){ const l=ds.links[i]; if(l&&l.subgraph) await collectAndExtractMedia(l.subgraph, zip, pathPrefix+"subgraphs/link"+i+"/", seen); }
  for(const _r in (ds._subgraphs||{})) await collectAndExtractMedia(ds._subgraphs[_r], zip, pathPrefix+"subgraphs/"+_r+"/", seen);
}

rehydrate_images.code:
function rehydrateImages(dataset, zip, pathPrefix, seen){ seen=seen||new Set(); if(!dataset||seen.has(dataset)) return; seen.add(dataset);
  const nodes=dataset.nodes||{};
  for(const id of Object.keys(nodes)){ const nd=nodes[id];
    for(const [field,folder] of MEDIA_FIELDS){ const v=nd[field];
      if(v && v.indexOf(pathPrefix+folder+"/")===0){ const zf=zip.file(v);
        if(zf){ const ext=v.split(".").pop().toLowerCase(), mime="image/"+(ext==="jpg"?"jpeg":ext);
          nd[field]="data:"+mime+";base64,"+(await zf.async("base64")); } } }
    if(nd.subgraph) await rehydrateImages(nd.subgraph, zip, pathPrefix+"subgraphs/"+id+"/", seen);
  }
  for(let i=0;i<(dataset.links||[]).length;i++){ const l=dataset.links[i]; if(l&&l.subgraph) await rehydrateImages(l.subgraph, zip, pathPrefix+"subgraphs/link"+i+"/", seen); }
  for(const _r in (dataset._subgraphs||{})) await rehydrateImages(dataset._subgraphs[_r], zip, pathPrefix+"subgraphs/"+_r+"/", seen);
}

parse_json_or_zip.code:
function parseJsonOrZip(file){
  if(/\.zip$/i.test(file.name)){
    if(typeof JSZip==="undefined") throw new Error("reading .zip bundles needs the JSZip library (internet required)");
    const zip=await JSZip.loadAsync(file), df=zip.file("data.json");
    if(!df) throw new Error("no data.json inside the zip");
    const data=JSON.parse(await df.async("string")); await rehydrateImages(data, zip, ""); return rehydratePool(data);
  }
  return rehydratePool(JSON.parse(await file.text()));
}

