function runSearch(){
  const term=qEl.value.trim().toLowerCase();
  resultsEl.innerHTML=""; qMatches=[]; qSel=-1;
  if(!term){ resultsEl.style.display="none"; return; }
  const ids=Model.ids, n=Model.count(), hits=[];
  for(let i=0;i<n && hits.length<60;i++){ const nd=Model.nodeById(ids[i]), nm=(nd&&nd.name)||ids[i];
    if(nm.toLowerCase().indexOf(term)>=0) hits.push({id:ids[i], name:nm, group:nd&&nd.group}); }
  hits.sort((a,b)=>{ const ap=a.name.toLowerCase().startsWith(term)?0:1, bp=b.name.toLowerCase().startsWith(term)?0:1; return ap-bp || a.name.localeCompare(b.name); });
  qMatches=hits.slice(0,10);
  if(!qMatches.length){ resultsEl.style.display="none"; return; }
  qMatches.forEach(m=>{ const d=document.createElement("div"); const g=m.group&&(Model.raw.groups||{})[m.group];
