function fetchGraphManifest(){
  try{ const r=await fetch(GRAPHS_DIR+"manifest.json",{cache:"no-store"});
    if(r.ok){ const j=await r.json(); const arr=Array.isArray(j)?j:(j&&Array.isArray(j.graphs)?j.graphs:[]);
      return arr.map(e=>typeof e==="string"?{file:e}:e).filter(e=>e&&e.file); } }catch(_){}
  try{ const r=await fetch(GRAPHS_DIR,{cache:"no-store"});
    if(r.ok){ const html=await r.text(), out=[], seen=new Set(), re=/href="([^"?]+\.(?:json|zip))"/gi; let m;
      while((m=re.exec(html))){ const fn=m[1].split("/").pop(); if(fn && fn.toLowerCase()!=="manifest.json" && !seen.has(fn)){ seen.add(fn); out.push({file:fn}); } }
      return out; } }catch(_){}
