        mg.onclick=async (ev)=>{ ev.stopPropagation(); sub.textContent="Merging \u201C"+title+"\u201D\u2026"; sub.style.color=""; try{ const doc=await fetchGraphDoc(url, e.file); closeLauncher(); mergeInto(doc); }catch(err){ sub.textContent="Couldn\u2019t merge \u201C"+title+"\u201D: "+err.message; sub.style.color="#e0a24a"; } };
        row.appendChild(main); row.appendChild(mg); list.appendChild(row); });
    }
    list.appendChild(card("Start a new graph", "Begin from a blank canvas.", ()=>chooseDoc({title:"Untitled graph", start:"n1", nodes:{n1:{name:"New node"}}, links:[], groups:{}, types:{}}), "action"));
      list.appendChild(card("Open a file\u2026", "Load a .json or .zip from your device.", async ()=>{ const d=await FileSource.pick(); if(d) chooseDoc(d); }, "action"));
      list.appendChild(card("Merge a file\u2026", "Combine a .json or .zip into the current graph.", async ()=>{ const d=await FileSource.pick(); if(d){ closeLauncher(); mergeInto(d); } }, "action"));
    { const ab=document.createElement("button"); ab.className="lc-about"; ab.type="button"; ab.textContent="About & how to use"; ab.onclick=()=>openAbout(); list.appendChild(ab); }
